function getZerofoxTranslation(key, lang) {
    return (zerofoxTranslations[lang] && zerofoxTranslations[lang][key]) ||
           (zerofoxTranslations.en && zerofoxTranslations.en[key]) || null;
}

function applyZerofoxTranslations(lang) {
    let count = 0;
    document.querySelectorAll("[data-i18n]").forEach(el => {
        const key = el.getAttribute("data-i18n");
        if (key && (key.startsWith("review.zerofox.") || key.startsWith("review.common."))) {
            const translation = getZerofoxTranslation(key, lang);
            if (translation) { el.textContent = translation; count++; }
        }
    });
    console.log(`Applied ${count} zerofox translations`);
}

window.addEventListener("languageChanged", e => setTimeout(() => applyZerofoxTranslations(e.detail.language), 200));

if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", () => applyZerofoxTranslations(window.i18n?.getCurrentLanguage() || "en"));
} else {
    applyZerofoxTranslations(window.i18n?.getCurrentLanguage() || "en");
}
